import urllib.request,urllib.error,json
url='https://app.ontrackegy.com/saas/console/device/v1/index.php'
body=json.dumps({'operation':'heartbeat'}).encode('utf-8')
req=urllib.request.Request(url,data=body,method='POST',headers={'Authorization':'Bearer header-check-not-a-real-token','Content-Type':'application/json'})
try:
 with urllib.request.urlopen(req,timeout=12) as response: code=response.status;raw=response.read(500)
except urllib.error.HTTPError as err:code=err.code;raw=err.read(500)
try: data=json.loads(raw)
except Exception: data={'error':'non_json_http_response'}
print(json.dumps({'http_status':code,'api_error':data.get('error'),'authorization_header_forwarded':data.get('error')=='device_not_authorized'}))
